async def _load_ready_ingestion_job(
    uow: CanonicalUnitOfWork,
    ingestion_job_id: uuid.UUID,
    *,
    should_lock: bool,
) -> IngestionJob:
    """Load a ready ingestion job, optionally retaining its row lock."""
    if should_lock:
        job = await uow.ingestion_jobs.get_for_update(ingestion_job_id)
    else:
        job = await uow.ingestion_jobs.get(ingestion_job_id)
    if job is None:
        raise IngestionJobNotFoundError(str(ingestion_job_id))
    if job.intake_state is not IntakeState.READY_FOR_GENERATION:
        raise IngestionJobNotReadyError(ingestion_job_id)
    return job

async def get_by_idempotency_key(
    self,
    idempotency_key: str,
) -> WorkflowCheckpoint | None:
    """Return the checkpoint for an idempotency key."""
    result = await self._session.execute(
        select(WorkflowCheckpointRecord).where(
            WorkflowCheckpointRecord.idempotency_key == idempotency_key
        )
    )
    record = result.scalar_one_or_none()
    _log_event(
        "debug",
        "sql_checkpoint_store.get_by_idempotency_key",
        idempotency_key=idempotency_key,
        found=record is not None,
    )
    if record is None:
        return None
    return _map_checkpoint(record)

def _has_blank_first_choice_message_content(payload: object) -> bool:
    """Return whether the first choice has blank message content."""
    if not _is_string_keyed_mapping(payload):
        return False
    payload_mapping = typ.cast("cabc.Mapping[str, object]", payload)
    choices = payload_mapping.get("choices")
    if not isinstance(choices, list) or not choices:
        return False
    first_choice = choices[0]
    if not _is_string_keyed_mapping(first_choice):
        return False
    choice_mapping = typ.cast("cabc.Mapping[str, object]", first_choice)
    message = choice_mapping.get("message")
    if not _is_string_keyed_mapping(message):
        return False
    message_mapping = typ.cast("cabc.Mapping[str, object]", message)
    content = message_mapping.get("content")
    return isinstance(content, str) and not content.strip()
